// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address target, bool shouldBeFrozen) public {
        address owner = address(this);
        vm.prank(owner);
        c.mintToken(owner, 1000);

        vm.prank(owner);
        c.freezeAccount(target, shouldBeFrozen);

        vm.prank(owner);
        c.burn(1);

        bool frozenAfter = c.frozenAccount(target);
        assertTrue(frozenAfter == shouldBeFrozen);
    }
}
